//! Adds review **edit history**: an `edited_at` column on `review` and a new
//! `review_revision` table.
//!
//! A reviewer may edit a published review to correct a mistake. Rather than
//! silently overwriting, each edit preserves the prior version as a `review_revision`
//! row carrying the reviewer's explanatory `note` and the autogenerated `diff` (a
//! JSON [`ReviewDiff`](../../test_cabinet_core/review/struct.ReviewDiff.html)) of what
//! changed. `review.reviewed_at` keeps meaning "first submitted"; the new nullable
//! `review.edited_at` records the most recent edit (null until the first edit). The
//! history is public — it is exported into the snapshot alongside the review — so a
//! reader can see how a review evolved.

use sea_orm_migration::prelude::*;

#[derive(DeriveMigrationName)]
pub struct Migration;

#[async_trait::async_trait]
impl MigrationTrait for Migration {
    async fn up(&self, manager: &SchemaManager) -> Result<(), DbErr> {
        // Nullable: a review that has never been edited has no edit timestamp
        // (distinct from `reviewed_at`, which every review carries).
        manager
            .alter_table(
                Table::alter()
                    .table(Review::Table)
                    .add_column(ColumnDef::new(Review::EditedAt).string())
                    .to_owned(),
            )
            .await?;

        manager
            .create_table(
                Table::create()
                    .table(ReviewRevision::Table)
                    .if_not_exists()
                    .col(
                        ColumnDef::new(ReviewRevision::Id)
                            .string()
                            .not_null()
                            .primary_key(),
                    )
                    .col(ColumnDef::new(ReviewRevision::ReviewId).string().not_null())
                    // RFC 3339 of when this edit was made; also stored on `review.edited_at`
                    // for the newest revision.
                    .col(ColumnDef::new(ReviewRevision::EditedAt).string().not_null())
                    // The reviewer's note explaining the edit (required on every edit).
                    .col(ColumnDef::new(ReviewRevision::Note).text().not_null())
                    // The autogenerated `ReviewDiff` from the prior content to the new,
                    // as a JSON object.
                    .col(ColumnDef::new(ReviewRevision::Diff).text().not_null())
                    .foreign_key(
                        ForeignKey::create()
                            .name("fk_review_revision_review")
                            .from(ReviewRevision::Table, ReviewRevision::ReviewId)
                            .to(Review::Table, Review::Id)
                            .on_delete(ForeignKeyAction::Cascade),
                    )
                    .to_owned(),
            )
            .await?;

        // A review's revisions are read together and ordered by `edited_at`, so index
        // the FK to keep that lookup cheap.
        manager
            .create_index(
                Index::create()
                    .if_not_exists()
                    .name("idx_review_revision_review")
                    .table(ReviewRevision::Table)
                    .col(ReviewRevision::ReviewId)
                    .to_owned(),
            )
            .await?;

        Ok(())
    }

    async fn down(&self, manager: &SchemaManager) -> Result<(), DbErr> {
        manager
            .drop_table(Table::drop().table(ReviewRevision::Table).to_owned())
            .await?;
        manager
            .alter_table(
                Table::alter()
                    .table(Review::Table)
                    .drop_column(Review::EditedAt)
                    .to_owned(),
            )
            .await?;
        Ok(())
    }
}

#[derive(DeriveIden)]
enum Review {
    Table,
    Id,
    EditedAt,
}

#[derive(DeriveIden)]
enum ReviewRevision {
    Table,
    Id,
    ReviewId,
    EditedAt,
    Note,
    Diff,
}
